
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wp04_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wp04", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.457318106581429e+00, -4.374897129180365e+00, -4.259470602049581e+00, -4.099712882765760e+00, -3.882309862407366e+00, -3.593564578213593e+00, -3.223163313245339e+00, -2.770876184066104e+00, -2.255161286572628e+00, -1.715548597905036e+00, -1.186015318614275e+00, -7.902886825584874e-01, -6.792190451876797e-01, -5.739464205668342e-01, -4.327108068191629e-01, -2.942724801064086e-01, -1.861270840238419e-01, -1.119333090329202e-01, -6.615368587617633e-02, -4.155589900607328e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


